$ErrorActionPreference = "Stop"

$root = (Get-Location).Path
$ws = Join-Path $root "runtime\workspaces\ahos-autopilot"
$pkg = Join-Path $ws "ahos_core"
$python = Join-Path $root ".venv\Scripts\python.exe"
$envRuntime = Join-Path $root ".env.runtime"

$providerRegistryPath = Join-Path $pkg "ahos\provider_registry.py"
$runpodPath = Join-Path $pkg "ahos\runpod_ltx2.py"
$testRegistryPath = Join-Path $pkg "tests\test_provider_registry.py"
$testRunPodPath = Join-Path $pkg "tests\test_runpod_ltx2.py"
$backlogPath = Join-Path $pkg "STUDIO_BACKLOG.json"
$reportPath = Join-Path $pkg "reports\STUDIO-005-runpod-provider-upgrade.json"

$privateRoot = Join-Path $root "runtime\private\animation-studio"
$privateConfig = Join-Path $privateRoot "media-providers.local.json"
$patcher = Join-Path $env:TEMP "studio-005-provider-backlog.py"

$endpointId = "dnwqoolyprqr69"

Write-Host "=== STUDIO-005 PROVIDER UPGRADE: EXISTING RUNPOD LTX-2 ==="
Write-Host "Existing endpoint: miniverse-ltx2-video"
Write-Host "Paid RunPod execution during this upgrade: 0"
Write-Host "Render jobs submitted: 0"
Write-Host ""

if (-not (Test-Path $python)) { throw "AHOS Python venv not found." }
if (-not (Test-Path $pkg)) { throw "AHOS package not found." }

New-Item -ItemType Directory -Force -Path (Split-Path $reportPath -Parent) | Out-Null
New-Item -ItemType Directory -Force -Path $privateRoot | Out-Null

[IO.File]::WriteAllBytes(
    $providerRegistryPath,
    [Convert]::FromBase64String("")
)
[IO.File]::WriteAllBytes(
    $runpodPath,
    [Convert]::FromBase64String("")
)
[IO.File]::WriteAllBytes(
    $testRegistryPath,
    [Convert]::FromBase64String("")
)
[IO.File]::WriteAllBytes(
    $testRunPodPath,
    [Convert]::FromBase64String("")
)
[IO.File]::WriteAllBytes(
    $privateConfig,
    [Convert]::FromBase64String("")
)
[IO.File]::WriteAllBytes(
    $patcher,
    [Convert]::FromBase64String("")
)

# Add only non-secret RunPod routing settings to .env.runtime.
# Never overwrite or print any existing secret.
if (-not (Test-Path $envRuntime)) {
    New-Item -ItemType File -Path $envRuntime -Force | Out-Null
}

$envText = Get-Content $envRuntime -Raw -ErrorAction SilentlyContinue
if ($null -eq $envText) { $envText = "" }

function Set-NonSecretEnv([string]$name, [string]$value) {
    $script:envText = $script:envText -replace "(?m)^$([regex]::Escape($name))=.*\r?\n?", ""
    if ($script:envText.Length -gt 0 -and -not $script:envText.EndsWith("`n")) {
        $script:envText += "`r`n"
    }
    $script:envText += "$name=$value`r`n"
}

Set-NonSecretEnv "RUNPOD_LTX2_ENDPOINT_ID" $endpointId
Set-NonSecretEnv "AHOS_MEDIA_PROVIDER_PREFERRED" "runpod-ltx2"
Set-NonSecretEnv "AHOS_MEDIA_EXECUTION_ENABLED" "false"
Set-NonSecretEnv "AHOS_PAID_MEDIA_ENABLED" "false"

[IO.File]::WriteAllText($envRuntime, $envText, [Text.UTF8Encoding]::new($false))

$apiKeyPresent = $false
if ($env:RUNPOD_API_KEY) {
    $apiKeyPresent = $true
} else {
    $line = Get-Content $envRuntime -ErrorAction SilentlyContinue |
        Where-Object { $_ -match '^\s*RUNPOD_API_KEY\s*=\s*\S+' } |
        Select-Object -First 1
    if ($line) { $apiKeyPresent = $true }
}

Write-Host "RUNPOD API KEY PRESENT (value hidden):" $apiKeyPresent
Write-Host "Execution remains disabled regardless of key presence."

$old = $env:PYTHONPATH
Push-Location $pkg
try {
    $env:PYTHONPATH = $pkg

    Write-Host "Running provider registry + RunPod adapter tests..."
    & $python -m pytest tests\test_provider_registry.py tests\test_runpod_ltx2.py -q
    if ($LASTEXITCODE -ne 0) {
        throw "RunPod provider focused tests failed."
    }

    Write-Host "Running full AHOS + Studio regression suite..."
    & $python -m pytest -q
    if ($LASTEXITCODE -ne 0) {
        throw "Full regression suite failed."
    }

    & $python $patcher $backlogPath
    if ($LASTEXITCODE -ne 0) {
        throw "STUDIO-005 backlog update failed."
    }
}
finally {
    Pop-Location
    $env:PYTHONPATH = $old
    Remove-Item $patcher -Force -ErrorAction SilentlyContinue
}

$report = @{
    studio_step = "STUDIO-005 provider upgrade"
    status = "PASS"
    endpoint_name = "miniverse-ltx2-video"
    endpoint_id = $endpointId
    provider_registry = "PASS"
    local_comfyui_provider = "AVAILABLE_AS_OPTION"
    runpod_ltx2_provider = "READY"
    runpod_api_key_present = $apiKeyPresent
    paid_execution_default = "BLOCKED"
    owner_approval_gate = "PASS"
    execution_enable_gate = "PASS"
    paid_provider_gate = "PASS"
    live_runpod_calls = 0
    render_jobs_submitted = 0
    api_spend_usd = 0
}
$report | ConvertTo-Json -Depth 6 |
    Set-Content -Path $reportPath -Encoding UTF8

git -C $ws add `
    ahos_core/ahos/provider_registry.py `
    ahos_core/ahos/runpod_ltx2.py `
    ahos_core/tests/test_provider_registry.py `
    ahos_core/tests/test_runpod_ltx2.py `
    ahos_core/STUDIO_BACKLOG.json `
    ahos_core/reports/STUDIO-005-runpod-provider-upgrade.json

$staged = git -C $ws diff --cached --name-only
if ($staged -match "\.env\.runtime|media-providers\.local") {
    throw "Privacy guard failed: private config or runtime env was staged."
}

if ($staged) {
    git -C $ws -c user.name="Miniverse Autopilot" -c user.email="miniverse@local.invalid" `
        commit -m "feat(studio): add guarded RunPod LTX2 provider"
    if ($LASTEXITCODE -ne 0) { throw "git commit failed." }

    git -C $ws push origin HEAD
    if ($LASTEXITCODE -ne 0) { throw "git push failed." }
}

Write-Host ""
Write-Host "=== STUDIO-005 RUNPOD PROVIDER UPGRADE COMPLETE ==="
Write-Host "Existing RunPod LTX-2 endpoint registered: PASS"
Write-Host "Multi-provider media registry: PASS"
Write-Host "Local ComfyUI kept as optional provider: PASS"
Write-Host "RunPod /run + /runsync + /status + /cancel adapter: PASS"
Write-Host "Existing worker contract (ping/bootstrap/render): PASS"
Write-Host "Secrets kept environment-only: PASS"
Write-Host "Paid execution default: BLOCKED"
Write-Host "Owner + execution + paid-provider triple gate: PASS"
Write-Host "Live RunPod calls: 0"
Write-Host "Render submissions: 0"
Write-Host "API spend: USD 0"
Write-Host ""
Write-Host "RUNPOD API KEY PRESENT (value hidden):" $apiKeyPresent
Write-Host "NEXT: verify credentials without exposing them, then perform ONE owner-approved paid health ping when you choose."
